script:
(function () {
  'use strict';
  // Credit card payoff. Interest each month = balance x APR / 12 (cards accrue daily on the
  // average daily balance; the monthly approximation is within a few cents per month).
  // Each month: add interest, new charges and (every 12th month) the annual fee, then pay.
  // "Pay off by" mode finds the smallest monthly payment (to the cent) that clears the debt
  // in the target number of months, by bisection over the same simulation.
  // Verified (scratchpad tests/cc.test.js): with no charges or fee the simulation matches the
  // closed forms n = -ln(1 - rB/P) / ln(1 + r) and P = rB / (1 - (1 + r)^-n):
  //   $8,000 at 18%, $200/month -> 62 months (closed form 61.54), total interest $4,308.98;
  //   $8,000 at 18% in 24 months -> $399.40/month (closed form $399.39, rounded up to the cent);
  //   $3,000 at 0%, $250/month -> 12 months, $0 interest; payment at or below the first
  //   month's interest is reported as never paying off.
  var MAX_MONTHS = 600;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function simulate(balance, apr, payment, charges, fee, keepRows) {
    var r = apr / 12, bal = balance, interestTotal = 0, paidTotal = 0, rows = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = bal * r;
      bal += interest + charges + (m % 12 === 0 ? fee : 0);
      var pay = Math.min(payment, bal);
      bal -= pay;
      interestTotal += interest;
      paidTotal += pay;
      if (keepRows) rows.push({ month: m, payment: pay, interest: interest, balance: Math.max(bal, 0) });
      if (bal <= 0.005) return { months: m, interest: interestTotal, paid: paidTotal, rows: rows, paidOff: true };
    }
    return { months: MAX_MONTHS, interest: interestTotal, paid: paidTotal, rows: rows, paidOff: false };
  }

  function paymentFor(balance, apr, months, charges, fee) {
    var r = apr / 12;
    var lo = 0, hi = (balance + (charges + fee) * months) * Math.pow(1 + r, months) + 1;
    for (var i = 0; i < 200; i++) {
      var mid = (lo + hi) / 2;
      var s = simulate(balance, apr, mid, charges, fee, false);
      if (s.paidOff && s.months <= months) hi = mid; else lo = mid;
    }
    var p = Math.ceil(hi * 100 - 1e-6) / 100;
    var check = simulate(balance, apr, p, charges, fee, false);
    if (!(check.paidOff && check.months <= months)) p += 0.01;
    return p;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearResults(message) {
    ['ccPrimary', 'ccInterest', 'ccTotal', 'ccDate'].forEach(function (id) { set(id, '–'); });
    set('ccPrimaryNote', message || '');
    document.getElementById('ccSchedule').innerHTML = '';
  }

  function update() {
    var mode = document.getElementById('ccMode').value;
    document.getElementById('ccPaymentField').hidden = mode !== 'payment';
    document.getElementById('ccMonthsField').hidden = mode !== 'months';

    var balance = num('ccBalance'), apr = num('ccRate'), payment = num('ccPayment'),
        months = Math.round(num('ccMonths')), charges = num('ccCharges'), fee = num('ccFee');
    if (isNaN(charges)) charges = 0;
    if (isNaN(fee)) fee = 0;
    var error = document.getElementById('ccError');
    var bad = isNaN(balance) || isNaN(apr) || balance <= 0 || apr < 0 || apr > 100 || charges < 0 || fee < 0 ||
              (mode === 'payment' && (isNaN(payment) || payment <= 0)) ||
              (mode === 'months' && (isNaN(months) || months < 1 || months > MAX_MONTHS));
    error.hidden = !bad;
    if (bad) {
      error.textContent = mode === 'payment'
        ? 'Enter a balance above $0, an APR from 0 to 100% and a monthly payment above $0. Charges and fees cannot be negative.'
        : 'Enter a balance above $0, an APR from 0 to 100% and a payoff goal of 1 to 600 months. Charges and fees cannot be negative.';
      clearResults('');
      return;
    }
    apr = apr / 100;
    if (mode === 'months') payment = paymentFor(balance, apr, months, charges, fee);

    var s = simulate(balance, apr, payment, charges, fee, true);
    if (!s.paidOff) {
      error.hidden = false;
      error.textContent = 'At ' + money.format(payment) + ' a month the balance is not paid off within 50 years. ' +
        'The first month adds about ' + money.format(balance * apr / 12 + charges) + ' in interest and new charges, so pay more than that.';
      clearResults('');
      return;
    }
    if (mode === 'months') {
      set('ccPrimaryLabel', 'Monthly payment needed');
      set('ccPrimary', money.format(payment));
      set('ccPrimaryNote', 'Pays off in ' + duration(s.months) + '.');
    } else {
      set('ccPrimaryLabel', 'Time to pay off');
      set('ccPrimary', duration(s.months));
      set('ccPrimaryNote', s.months + (s.months === 1 ? ' payment' : ' payments') + '.');
    }
    set('ccInterest', money.format(s.interest));
    set('ccTotal', money.format(s.paid));
    var now = new Date();
    set('ccDate', monthName.format(new Date(now.getFullYear(), now.getMonth() + s.months, 1)));
    document.getElementById('ccSchedule').innerHTML = s.rows.map(function (row) {
      return '<tr><td>' + row.month + '</td><td>' + money.format(row.payment) + '</td><td>' +
             money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ccForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
